-- Consultas que geram supabase/estrutura-atual.sql (só leem o banco).
-- Rode pelo conector (execute_sql) e cole o resultado nas seções do arquivo.

-- 1. Tabelas (colunas e regras)
with t as (select c.oid, c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p') order by c.relname)
select string_agg(
 'create table public.'||quote_ident(t.relname)||' ('||E'\n'||
 (select string_agg('  '||quote_ident(a.attname)||' '||format_type(a.atttypid,a.atttypmod)
   ||case when a.attidentity='a' then ' generated always as identity' when a.attidentity='d' then ' generated by default as identity' else '' end
   ||case when a.attgenerated='s' then ' generated always as ('||pg_get_expr(d.adbin,d.adrelid)||') stored' when d.adbin is not null then ' default '||pg_get_expr(d.adbin,d.adrelid) else '' end
   ||case when a.attnotnull then ' not null' else '' end, E',\n' order by a.attnum)
  from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
  where a.attrelid=t.oid and a.attnum>0 and not a.attisdropped)
 ||coalesce((select E',\n'||string_agg('  constraint '||quote_ident(co.conname)||' '||pg_get_constraintdef(co.oid), E',\n' order by case co.contype when 'p' then 0 when 'u' then 1 when 'c' then 2 else 3 end, co.conname) from pg_constraint co where co.conrelid=t.oid),'')
 ||E'\n);', E'\n\n' order by t.relname) as tabelas from t;

-- 2. Índices, visões, funções, gatilhos, RLS, políticas e permissões
select
(select string_agg(indexdef||';', E'\n' order by tablename, indexname) from pg_indexes i where schemaname='public' and not exists (select 1 from pg_constraint c where c.conname=i.indexname)) as indices,
(select string_agg('create or replace view public.'||quote_ident(c.relname)||coalesce(' with ('||array_to_string(c.reloptions,', ')||')','')||' as'||E'\n'||pg_get_viewdef(c.oid), E'\n\n' order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='v') as visoes,
(select string_agg(pg_get_functiondef(p.oid)||';', E'\n' order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f') as funcoes,
(select string_agg(format('grant execute on function %s to %s;', p.oid::regprocedure, r), E'\n') from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join unnest(array['anon','authenticated']) r where n.nspname='public' and has_function_privilege(r, p.oid, 'execute')) as funcoes_liberadas,
(select string_agg(pg_get_triggerdef(t.oid)||';', E'\n' order by n.nspname, c.relname, t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','auth') and not t.tgisinternal) as gatilhos,
(select string_agg('alter table public.'||quote_ident(c.relname)||' enable row level security;', E'\n' order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relrowsecurity) as rls,
(select string_agg('create policy '||quote_ident(policyname)||' on public.'||quote_ident(tablename)||' as '||lower(permissive)||' for '||lower(cmd)||' to '||array_to_string(roles,', ')||coalesce(' using ('||qual||')','')||coalesce(' with check ('||with_check||')','')||';', E'\n' order by tablename, policyname) from pg_policies where schemaname='public') as politicas,
(select string_agg(format('grant %s on public.%I to %s;', privs, table_name, grantee), E'\n' order by table_name, grantee) from (select table_name, grantee, string_agg(lower(privilege_type), ', ' order by privilege_type) privs from information_schema.role_table_grants where table_schema='public' and grantee in ('anon','authenticated') group by 1,2) g) as permissoes,
(select string_agg(format('grant update (%s) on public.%I to %s;', cols, table_name, grantee), E'\n') from (select table_name, grantee, string_agg(column_name, ', ' order by column_name) cols from information_schema.column_privileges where table_schema='public' and grantee in ('anon','authenticated') and privilege_type='UPDATE' and table_name in ('perfis','recados','recados_uteis') group by 1,2) x) as permissoes_colunas;
